sp_widget.client_script:
api.controller = function ($scope, $element, $http, $q, $filter, $window, $timeout) {

    var c = this;

    // =========================================================
    // STEP CONFIGURATION
    // =========================================================

    c.titles = [
        'Vehicle information',
        'Owner details',
        'Warranty selection',
        'Documents',
        'Review and submit'
    ];

    c.subs = [
        'Vehicle and purchase details',
        'Owner and contact information',
        'Choose your warranty plan',
        'Upload the required documents',
        'Review everything before submitting'
    ];

    c.icons = ['fa-car', 'fa-user', 'fa-shield', 'fa-upload', 'fa-check-square-o'];

    c.idTypes = ["Driver's License", "State ID Card", "Passport", "Military ID"];

    c.docs = [
        { key: 'invoice', label: 'Purchase invoice' },
        { key: 'rc',      label: 'Vehicle registration certificate (RC)' },
        { key: 'idproof', label: 'Owner ID proof' }
    ];


    // =========================================================
    // INITIAL STATE
    // =========================================================

    c.cur = 1;
    c.err = '';
    c.msg = '';
    c.done = false;
    c.busy = false;
    c.files = {};

    c.v = c.data.v || {};
    c.data.o = c.data.o || {};
    c.data.plans = c.data.plans || [];

    var o = c.data.o;

    // Aaj ki date browser ke hisaab se (server UTC se 1 din ka farak aa sakta hai)
    var todayStr = $filter('date')(new Date(), 'yyyy-MM-dd');


    // =========================================================
    // FORM DATA
    // =========================================================

    c.f = {
        delivery: new Date(todayStr + 'T00:00:00'),

        regNo: '',
        invoice: '',

        colour: c.v.colour || '',
        odometer: c.v.odometer || 0,

        name: o.name || '',
        mobile: o.mobile || '',
        email: o.email || '',

        idType: '',
        idNo: '',

        street: o.street || '',
        city: o.city || '',
        state: o.state || '',
        pin: o.pin || '',
        country: o.country || 'India',

        plan: c.data.plans.length ? c.data.plans[0].id : '',

        terms: false
    };


    // =========================================================
    // SELECTED WARRANTY PLAN
    // =========================================================

    c.sel = function () {

        for (var i = 0; i < c.data.plans.length; i++) {
            if (c.data.plans[i].id == c.f.plan) {
                return c.data.plans[i];
            }
        }

        return {
            id: '',
            name: '',
            term: 0,
            totalTerm: 0,
            price: 0,
            coverageMileage: 0,
            deductible: 0
        };
    };


    // =========================================================
    // WARRANTY END DATE
    // =========================================================

    c.endDate = function (months) {

        if (!c.f.delivery) {
            return null;
        }

        var date = new Date(c.f.delivery);
        var day = date.getDate();

        date.setMonth(date.getMonth() + (parseInt(months, 10) || 0));

        // 31 Jan + 1 month jaisi halat mein month-end pe rakho (server jaisa)
        if (date.getDate() != day) {
            date.setDate(0);
        }

        date.setDate(date.getDate() - 1);

        return date;
    };


    // =========================================================
    // DRAFT (is device ke browser mein save hota hai)
    // Sensitive cheezein (ID number, documents, terms) save nahi hoti.
    // =========================================================

    var DRAFT_KEY = 'warranty_draft_' + (c.v.inv || '');
    var DRAFT_FIELDS = [
        'regNo', 'invoice', 'colour', 'odometer', 'mobile', 'email',
        'idType', 'street', 'city', 'state', 'pin', 'plan'
    ];

    function loadDraft() {
        if (!c.v.inv) { return; }

        try {
            var raw = $window.localStorage.getItem(DRAFT_KEY);
            if (!raw) { return; }

            var d = JSON.parse(raw);

            angular.forEach(DRAFT_FIELDS, function (k) {
                if (d[k] !== undefined && d[k] !== null && d[k] !== '') {
                    c.f[k] = d[k];
                }
            });

            if (d.delivery) {
                c.f.delivery = new Date(d.delivery + 'T00:00:00');
            }

            // Draft wala plan ab bhi available hai ya nahi
            var found = c.data.plans.some(function (p) { return p.id == c.f.plan; });
            if (!found) {
                c.f.plan = c.data.plans.length ? c.data.plans[0].id : '';
            }

            c.msg = 'Your saved draft was restored.';

        } catch (e) { /* draft kharab ho to ignore */ }
    }

    function clearDraft() {
        try { $window.localStorage.removeItem(DRAFT_KEY); } catch (e) {}
    }

    c.saveDraft = function () {

        if (!c.v.inv) { return; }

        try {
            var d = {};

            angular.forEach(DRAFT_FIELDS, function (k) {
                d[k] = c.f[k];
            });

            d.delivery = $filter('date')(c.f.delivery, 'yyyy-MM-dd') || '';

            $window.localStorage.setItem(DRAFT_KEY, JSON.stringify(d));

            c.err = '';
            c.msg = 'Draft saved on this device. ID number and documents are not saved.';

            $timeout(function () { c.msg = ''; }, 5000);

        } catch (e) {
            c.msg = '';
            c.err = 'The draft could not be saved on this device.';
        }
    };

    loadDraft();


    // =========================================================
    // VALIDATION
    // =========================================================

    function validate(step) {

        // STEP 1
        if (step == 1) {

            if (!c.v.inv) {
                return 'No vehicle is selected.';
            }

            if (!c.v.vin) {
                return 'VIN is missing from the selected Inventory record.';
            }

            if (!c.data.o.customer) {
                return 'No customer is set on this Inventory record. Add a Customer there first.';
            }

            if (!c.f.regNo) {
                return 'Enter the registration number.';
            }

            if (!c.f.delivery) {
                return 'Enter the purchase date.';
            }

            if ($filter('date')(c.f.delivery, 'yyyy-MM-dd') > todayStr) {
                return 'The purchase date cannot be in the future.';
            }

            if (!c.f.invoice) {
                return 'Enter the invoice number.';
            }
        }


        // STEP 2
        if (step == 2) {

            if (!c.f.mobile)  { return 'Enter the mobile number.'; }
            if (!c.f.email)   { return 'Enter a valid email address.'; }
            if (!c.f.idType)  { return 'Select the ID type.'; }
            if (!c.f.idNo)    { return 'Enter the ID number.'; }
            if (!c.f.street)  { return 'Enter the street address.'; }
            if (!c.f.city)    { return 'Enter the city.'; }
            if (!c.f.state)   { return 'Enter the state.'; }
            if (!c.f.pin)     { return 'Enter the PIN code.'; }
        }


        // STEP 3
        if (step == 3) {

            if (!c.data.plans.length) {
                return 'No eligible warranty plans are available for this vehicle.';
            }

            if (!c.f.plan) {
                return 'Select a warranty plan.';
            }
        }


        // STEP 4
        if (step == 4) {

            if (!c.files.invoice) { return 'Upload the purchase invoice.'; }
            if (!c.files.rc)      { return 'Upload the vehicle registration certificate (RC).'; }
            if (!c.files.idproof) { return 'Upload the owner ID proof.'; }
        }


        // STEP 5
        if (step == 5) {

            if (!c.f.terms) {
                return 'Accept the warranty terms and conditions.';
            }
        }

        return '';
    }


    // =========================================================
    // NAVIGATION
    // =========================================================

    c.go = function (target) {

        target = parseInt(target, 10);

        if (!target || target < 1 || target > 5) {
            return;
        }

        c.msg = '';

        if (target == c.cur) {
            c.err = '';
            return;
        }

        // Peeche jaana hamesha allowed hai
        if (target < c.cur) {
            c.err = '';
            c.cur = target;
            return;
        }

        // Aage jaane se pehle beech ke saare steps valid hone chahiye
        for (var step = c.cur; step < target; step++) {

            var error = validate(step);

            if (error) {
                c.err = error;
                c.cur = step;
                return;
            }
        }

        c.err = '';
        c.cur = target;
    };

    c.next = function () {

        if (c.cur >= 5) {
            return;
        }

        var error = validate(c.cur);

        if (error) {
            c.err = error;
            return;
        }

        c.err = '';
        c.msg = '';
        c.cur++;
    };

    c.back = function () {

        if (c.cur <= 1) {
            return;
        }

        c.err = '';
        c.msg = '';
        c.cur--;
    };


    // =========================================================
    // FILE SELECTION  (native listener: jqLite/jQuery dono mein chalta hai)
    // =========================================================

    var fileHandler = function (event) {

        var input = event.target;

        if (!input || input.type !== 'file') {
            return;
        }

        var key = input.getAttribute('data-key');
        var file = input.files && input.files[0];

        if (!key || !file) {
            return;
        }

        $scope.$apply(function () {

            // Maximum 5 MB
            if (file.size > 5 * 1024 * 1024) {
                c.err = 'The file is larger than 5 MB.';
                input.value = '';
                return;
            }

            // Sirf PDF, JPG, PNG (extension se check, kyunki file.type kabhi khaali aata hai)
            if (!/\.(pdf|jpe?g|png)$/i.test(file.name)) {
                c.err = 'Only PDF, JPG and PNG files are allowed.';
                input.value = '';
                return;
            }

            c.err = '';
            c.files[key] = file;
        });
    };

    $element[0].addEventListener('change', fileHandler);

    $scope.$on('$destroy', function () {
        $element[0].removeEventListener('change', fileHandler);
    });


    // =========================================================
    // ATTACHMENT UPLOAD
    // =========================================================

    function upload(file, key, sysId, regTable) {

        // File ke naam ke aage document type lagao, taaki record pe pehchaan ho sake
        var fileName = key + '_' + file.name;

        return $http.post(
            '/api/now/attachment/file' +
            '?table_name=' + encodeURIComponent(regTable) +
            '&table_sys_id=' + encodeURIComponent(sysId) +
            '&file_name=' + encodeURIComponent(fileName),
            file,
            {
                headers: {
                    'Content-Type': file.type || 'application/octet-stream'
                },
                transformRequest: angular.identity
            }
        );
    }


    // =========================================================
    // SUBMIT
    // =========================================================

    c.submit = function () {

        if (c.busy) {
            return;
        }

        var error = validate(5);

        if (error) {
            c.err = error;
            return;
        }

        c.err = '';
        c.msg = '';
        c.busy = true;

        var formData = angular.copy(c.f);

        formData.delivery = $filter('date')(c.f.delivery, 'yyyy-MM-dd') || '';
        formData.inv = c.v.inv;

        // Server Script ko batao ki submit karna hai
        c.data.action = 'submit';
        c.data.form = formData;

        c.server.update().then(function () {

            c.data.action = undefined;

            // Server side failure
            if (c.data.error || !c.data.newId) {
                c.err = c.data.error || 'Submission failed.';
                c.busy = false;
                return;
            }

            var newId = c.data.newId;
            var regTable = c.data.regTable;

            // Teeno documents upload karo
            $q.all(
                c.docs.map(function (doc) {
                    return upload(c.files[doc.key], doc.key, newId, regTable);
                })
            )
            .then(function () {

                c.ref = c.data.ref;
                c.valid = c.endDate(c.data.stdMonths + c.sel().term);
                clearDraft();
                c.done = true;
                c.busy = false;

            })
            .catch(function () {

                c.err =
                    'The registration was created (' + c.data.ref + '), ' +
                    'but one or more documents could not be uploaded. ' +
                    'Please contact support with this reference number.';

                c.busy = false;
            });

        }, function () {

            c.err = 'No response from the server. Please try again.';
            c.busy = false;

        });

    };

};

sp_widget.css:
/* ===== Warranty Registration Wizard: POORA CSS =====
   Widget ke CSS field mein jo kuch bhi hai use select-all karke hata do
   aur ye poora paste karo (isme pehle wala CSS + naye fixes dono hain). */

/* Portal ke Bootstrap ke margin/padding is widget ke andar reset karo */
.sn-chrome label{
  margin:0;
  max-width:none;
  display:block;
}

.sn-chrome p,
.sn-chrome h3{
  margin:0;
}

.sn-chrome{
  background:#fff;
  border:1px solid #c8d5e3;
  border-radius:12px;
  overflow:hidden;
  font-size:13px;
}

.sn-header{
  background:#1a3d66;
  padding:10px 16px;
  display:flex;
  align-items:center;
  justify-content:space-between;
}

.sn-logo{
  color:#fff;
  font-size:14px;
  font-weight:500;
  display:flex;
  align-items:center;
  gap:8px;
}

.sn-logo i{
  color:#72b8f5;
  font-size:18px;
}

.sn-nav{
  display:flex;
  align-items:center;
  gap:14px;
}

.sn-nav a{
  color:#aacfee;
  font-size:12px;
  text-decoration:none;
}

.sn-nav i{
  color:#aacfee;
}

.sn-avatar{
  width:28px;
  height:28px;
  border-radius:50%;
  background:#2d6a9f;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#fff;
  font-size:11px;
}

.sn-breadcrumb{
  background:#f0f4f8;
  border-bottom:1px solid #c8d5e3;
  padding:8px 16px;
  font-size:12px;
  color:#5a7a96;
  display:flex;
  align-items:center;
  gap:6px;
}

.sn-breadcrumb b{
  color:#1a3d66;
  font-weight:500;
}

.sn-ref{
  margin-left:auto;
  background:#1a3d66;
  color:#fff;
  font-size:11px;
  font-weight:500;
  padding:3px 8px;
  border-radius:3px;
}

.sn-body{
  display:grid;
  grid-template-columns:220px 1fr;
  min-height:500px;
}

.sn-sidebar{
  background:#f7f9fb;
  border-right:1px solid #c8d5e3;
  padding:16px 0;
}

.sn-sidebar-title{
  font-size:11px;
  font-weight:500;
  color:#5a7a96;
  text-transform:uppercase;
  letter-spacing:.07em;
  padding:0 16px 8px;
}

.sn-sidebar-item{
  padding:8px 16px;
  cursor:pointer;
  font-size:13px;
  color:#2d4a63;
  display:flex;
  align-items:center;
  gap:8px;
  border-left:3px solid transparent;
}

.sn-sidebar-item:hover{
  background:#eef3f8;
}

.sn-sidebar-item.active{
  background:#e6f0f8;
  border-left-color:#1a3d66;
  color:#1a3d66;
  font-weight:500;
}

.sn-sidebar-item i{
  width:18px;
  color:#5a7a96;
}

.sn-sidebar-item.active i{
  color:#1a3d66;
}

.sn-sidebar-item.done,
.sn-sidebar-item.done i{
  color:#27a060;
}

.sidebar-help{
  margin:20px 16px 8px;
  border-top:1px solid #c8d5e3;
  padding-top:16px;
}

.help-title{
  font-size:11px;
  color:#5a7a96;
  margin-bottom:8px;
  font-weight:500;
  text-transform:uppercase;
  letter-spacing:.06em;
}

.help-item{
  color:#2d6a9f;
  display:flex;
  align-items:center;
  gap:6px;
  font-size:12px;
  margin-bottom:8px;
}

.sn-right{
  min-width:0;
  display:flex;
  flex-direction:column;
}

.sn-main{
  padding:24px 28px;
  background:#fff;
  flex:1;
}

.sn-form-header{
  margin-bottom:20px;
}

.sn-form-heading{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
}

.sn-form-title{
  font-size:18px;
  font-weight:500;
  color:#1a3d66;
  margin-bottom:4px;
}

.sn-form-sub{
  font-size:13px;
  color:#5a7a96;
}

.sn-progress{
  font-size:12px;
  color:#5a7a96;
}

.step-indicator{
  display:flex;
  align-items:center;
  gap:6px;
  margin-top:10px;
  margin-bottom:16px;
}

.step-dot{
  width:8px;
  height:8px;
  border-radius:50%;
  background:#c8d5e3;
}

.step-dot.done{
  background:#27a060;
}

.step-dot.active{
  background:#1a3d66;
  width:24px;
  border-radius:4px;
}

.sn-section{
  background:#fff;
  border:1px solid #c8d5e3;
  border-radius:6px;
  margin-bottom:16px;
  overflow:hidden;
}

.sn-section-head{
  background:#e8eff7;
  border-bottom:1px solid #c8d5e3;
  padding:10px 16px;
  display:flex;
  align-items:center;
  gap:8px;
}

.sn-section-head i{
  color:#1a3d66;
  font-size:16px;
}

.sn-section-head span{
  font-size:13px;
  font-weight:500;
  color:#1a3d66;
}

.sn-section-body{
  padding:16px;
}

.sn-field-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px 20px;
}

.sn-field-grid.cols3{
  grid-template-columns:1fr 1fr 1fr;
}

.sn-field{
  display:flex;
  flex-direction:column;
  gap:5px;
}

.sn-field label,
.sn-doc-field label{
  font-size:12px;
  font-weight:500;
  color:#3d5a74;
}

.req{
  color:#c0392b;
  margin-left:2px;
}

.sn-input,
.sn-select{
  width:100%;
  height:auto;
  padding:7px 10px;
  font-size:13px;
  border:1px solid #a8bdd1;
  border-radius:4px;
  background:#fff;
  color:#1a2d3d;
  outline:none;
  box-shadow:none;
}

.sn-input:focus,
.sn-select:focus{
  border-color:#1a3d66;
  box-shadow:0 0 0 2px rgba(26,61,102,.12);
}

.sn-readonly{
  background:#f5f7fa;
  color:#5a7a96;
}

.sn-input:disabled,
.sn-select:disabled{
  background:#f5f7fa;
  cursor:not-allowed;
}

.info-banner,
.info-warning{
  border-radius:4px;
  padding:10px 14px;
  margin-bottom:16px;
  display:flex;
  align-items:flex-start;
  gap:10px;
}

.info-banner{
  background:#e6f0f8;
  border:1px solid #a8c4dc;
}

.info-warning{
  background:#fff8d9;
  border:1px solid #e9d978;
  color:#6a5b00;
}

.info-banner i{
  color:#1a3d66;
  margin-top:1px;
}

.info-warning i{
  color:#9a8500;
  margin-top:1px;
}

.info-banner p,
.info-warning span{
  margin:0;
  font-size:12px;
  line-height:1.6;
}

.warranty-card{
  border:1px solid #c8d5e3;
  border-radius:6px;
  padding:12px 14px;
  margin-bottom:10px;
  cursor:pointer;
  display:flex;
  align-items:flex-start;
  gap:12px;
  transition:.15s;
}

.warranty-card:hover{
  border-color:#1a3d66;
}

.warranty-card.selected{
  border-color:#1a3d66;
  background:#e6f0f8;
}

.warranty-card input{
  margin-top:2px;
  accent-color:#1a3d66;
}

.wc-info{
  flex:1;
}

.wc-name{
  font-size:13px;
  font-weight:500;
  color:#1a3d66;
  margin-bottom:3px;
}

.wc-desc{
  font-size:12px;
  color:#5a7a96;
  margin-bottom:5px;
}

.wc-meta{
  color:#2d4a63;
  font-size:12px;
}

.wc-badge{
  display:inline-block;
  background:#dff0d8;
  color:#2e6b3c;
  font-size:11px;
  font-weight:500;
  padding:2px 8px;
  border-radius:3px;
  margin-top:5px;
}

.wc-price{
  font-size:14px;
  font-weight:500;
  color:#1a3d66;
  margin-left:auto;
  white-space:nowrap;
}

.sn-doc-field{
  display:flex;
  flex-direction:column;
  gap:6px;
  margin-bottom:14px;
}

.upload-area{
  position:relative;
  border:1.5px dashed #a8bdd1;
  border-radius:6px;
  padding:20px;
  text-align:center;
  background:#f7f9fb;
  overflow:hidden;
}

.upload-area i{
  display:block;
  font-size:28px;
  color:#a8bdd1;
  margin-bottom:8px;
}

.upload-area > div{
  font-size:12px;
  color:#5a7a96;
}

.upload-area small{
  display:block;
  margin-top:4px;
  color:#5a7a96;
}

.upload-link{
  color:#1a3d66;
  font-weight:500;
  text-decoration:underline;
}

.upload-input{
  position:absolute;
  top:0;
  right:0;
  bottom:0;
  left:0;
  width:100%;
  height:100%;
  opacity:0;
  cursor:pointer;
}

.uploaded-file{
  display:flex;
  align-items:center;
  gap:10px;
  padding:8px 12px;
  background:#f7f9fb;
  border:1px solid #c8d5e3;
  border-radius:4px;
  margin-top:8px;
}

.uploaded-file i{
  color:#1a3d66;
}

.uploaded-file span{
  flex:1;
  font-size:12px;
  color:#2d4a63;
}

.upload-ok{
  color:#27a060 !important;
}

.edit-link{
  margin-left:auto;
  font-size:12px;
  color:#2d6a9f;
  cursor:pointer;
  text-decoration:none;
}

.terms-box{
  background:#f0f7ee;
  border:1px solid #a3d4b5;
  border-radius:6px;
  padding:12px 16px;
  display:flex;
  align-items:flex-start;
  gap:10px;
}

.terms-box input{
  margin-top:3px;
}

.terms-box label{
  font-size:12px;
  color:#2d4a63;
  line-height:1.6;
  font-weight:400;
}

.alert{
  font-size:12px;
  padding:10px 14px;
  margin-bottom:16px;
  border-radius:4px;
}

.sn-footer{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:14px 28px;
  border-top:1px solid #c8d5e3;
  background:#f0f4f8;
}

.footer-actions{
  display:flex;
  align-items:center;
  gap:10px;
}

.sn-btn{
  padding:8px 18px;
  border-radius:4px;
  font-size:13px;
  font-weight:500;
  cursor:pointer;
  border:none;
}

a.sn-btn{
  display:inline-block;
  text-decoration:none;
}

.sn-btn:disabled{
  opacity:.6;
  cursor:not-allowed;
}

.sn-btn-primary{
  background:#1a3d66;
  color:#fff;
}

.sn-btn-primary:hover{
  background:#14305a;
  color:#fff;
}

.sn-btn-secondary{
  background:#fff;
  color:#1a3d66;
  border:1px solid #a8bdd1;
}

.sn-btn-secondary:hover{
  background:#f0f4f8;
}

.sn-btn-success{
  background:#27a060;
  color:#fff;
}

.sn-btn-success:hover{
  background:#1f8a50;
}

.sn-empty{
  background:#fff;
  border:1px solid #c8d5e3;
  border-radius:12px;
  padding:48px;
  text-align:center;
  color:#5a7a96;
}

.sn-empty i{
  font-size:48px;
  color:#a8bdd1;
  margin-bottom:12px;
}

.success{
  padding:48px;
  text-align:center;
}

.success-icon{
  font-size:56px;
  color:#27a060;
  margin-bottom:12px;
}

.success-reference{
  display:inline-block;
  background:#f0f4f8;
  border:1px solid #c8d5e3;
  border-radius:6px;
  padding:14px 20px;
  margin:20px 0;
}

.success-reference small{
  display:block;
  font-size:11px;
  color:#5a7a96;
}

.success-reference div{
  font-size:18px;
  font-weight:500;
  color:#1a3d66;
}

.success-summary{
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:12px 36px;
  margin-bottom:24px;
}

.success-summary small{
  display:block;
  font-size:11px;
  color:#5a7a96;
  text-transform:uppercase;
}

.success-summary b{
  color:#1a3d66;
}

@media(max-width:768px){

  .sn-body{
    grid-template-columns:1fr;
  }

  .sn-sidebar{
    border-right:none;
    border-bottom:1px solid #c8d5e3;
  }

  .sn-field-grid,
  .sn-field-grid.cols3{
    grid-template-columns:1fr;
  }

  .sn-nav{
    display:none;
  }

  .sn-main{
    padding:18px;
  }

  .sn-footer{
    padding:12px 18px;
  }

}

sp_widget.script:
(function () {
  // ===== CONFIG =====
  var PREFIX = 'x_2190010_vinwar_0_';   // app scope prefix (scoped table names ke liye zaroori)
  var STD_MONTHS = 24;                  // standard manufacturer warranty (months)
  var TERM_IS_TOTAL = true;             // plan "Term (Months)" = TOTAL months (24/36/48/60)
  var CUR = '$';                        // plan cards pe currency symbol ('$' ya '₹')

  // ===== HELPERS =====
  function num(v) { return parseFloat(String(v || '0').replace(/[^0-9.]/g, '')) || 0; }

  function ext(v) {                     // extra months = total term - standard warranty
    var t = parseInt(String(v || '0').replace(/[^0-9]/g, ''), 10) || 0;
    return TERM_IS_TOTAL ? Math.max(t - STD_MONTHS, 0) : t;
  }

  function list(v) {                    // "Tesla, Ford,BMW" -> ['tesla','ford','bmw']
    return String(v || '').split(',').map(function (s) { return s.trim().toLowerCase(); })
                          .filter(function (s) { return s; });
  }

  function d10(v) { return String(v || '').substring(0, 10); }   // Date/Time ko yyyy-MM-dd bana do

  // List ka pehla field jo exist kare aur khaali na ho (field na mile to error nahi aata)
  function pick(gr, names) {
    for (var i = 0; i < names.length; i++)
      if (gr.isValidField(names[i]) && gr.getValue(names[i])) return String(gr.getValue(names[i]));
    return '';
  }

  // Pehla valid field set karo; na mile to log mein warning likho
  function setAny(gr, names, val) {
    for (var i = 0; i < names.length; i++) {
      if (gr.isValidField(names[i])) { gr.setValue(names[i], val); return true; }
    }
    gs.warn('WARRANTY_WIDGET: field nahi mila on ' + gr.getTableName() + ' -> ' + names.join(' / '));
    return false;
  }

  // Reference field kis table ko point karta hai (naam guess nahi karna padta)
  function refTable(gr, field) {
    try {
      if (gr.isValidField(field)) return String(gr.getElement(field).getReferenceTable() || '');
    } catch (e) {}
    return '';
  }

  // Table ka sahi naam: pehle prefix ke saath, phir bina prefix ke
  function tbl(shortName) {
    var cands = [PREFIX + shortName, shortName];
    for (var i = 0; i < cands.length; i++)
      if (new GlideRecord(cands[i]).isValid()) return cands[i];
    return PREFIX + shortName;
  }

  var T = {
    inv: tbl('inventory'),
    cust: tbl('customer_details'),
    plan: tbl('warranty_plan'),
    reg: tbl('warranty_registration')
  };

  data.today = new GlideDateTime().getLocalDate().getValue();   // yyyy-MM-dd (user ke timezone mein)
  data.stdMonths = STD_MONTHS;
  data.cur = CUR;
  data.regTable = T.reg;            // client attachments upload ke liye use karta hai
  data.v = {};
  data.o = {};
  data.plans = [];

  // 1) Inventory + Customer  (URL: ?id=warranty_reg&inv=<sys_id>)
  var invId = $sp.getParameter('inv') || (input && input.form && input.form.inv) || '';
  var inv = new GlideRecord(T.inv);
  if (invId && inv.get(invId)) {
    data.v = {
      inv: invId,
      vin: pick(inv, ['vin', 'vin_number']),
      mmt: pick(inv, ['make_model_trim']),
      year: pick(inv, ['model_year']),
      odometer: parseInt(pick(inv, ['odometer_reading']), 10) || 0,
      colour: pick(inv, ['exterior_interior_color', 'exterior_color', 'colour']).substring(0, 40),
      dealer: inv.isValidField('dealer_name') ? inv.getDisplayValue('dealer_name') : ''
    };

    // Customer reference Inventory pe 'customer_name' naam se hai
    var custField = inv.isValidField('customer_name') ? 'customer_name' : 'customer';
    var cid = pick(inv, [custField]);
    var custTable = refTable(inv, custField) || T.cust;
    var c = new GlideRecord(custTable);
    if (cid && c.get(cid)) {
      var a1 = pick(c, ['address_line_1']), st = pick(c, ['street']);
      data.o = {
        customer: c.getUniqueValue(),
        name: pick(c, ['name', 'customer_name', 'full_name']) || c.getDisplayValue(),
        mobile: pick(c, ['number', 'mobile', 'phone']),
        email: pick(c, ['email']),
        street: (a1 && st && a1 != st ? a1 + ', ' + st : (a1 || st)).substring(0, 100),
        city: pick(c, ['city']),
        state: pick(c, ['state']),
        pin: pick(c, ['zip_code', 'pin_code']),
        country: pick(c, ['country']) || 'India'
      };
    }
  }

  // 2) Plans: active + date range + vehicle ki Make aur Model Year se match
  if (data.v.inv) {
    var vMmt = String(data.v.mmt || '').trim().toLowerCase();
    var vYear = String(data.v.year || '').replace(/[^0-9]/g, '');
    var p = new GlideRecord(T.plan);
    if (p.isValidField('status')) {
      var qc = p.addQuery('status', 'active');
      qc.addOrCondition('status', 'Active');
    }
    p.query();
    while (p.next()) {
      var eff = d10(p.getValue('effective_date')), exp = d10(p.getValue('expiration_date'));
      if (eff && eff > data.today) continue;        // abhi effective nahi
      if (exp && exp < data.today) continue;        // expire ho chuka
      var makes = list(p.getValue('applicable_makes'));
      var years = list(p.getValue('applicable_model_years'));
      if (makes.length && vMmt) {
        var okMake = makes.some(function (m) { return vMmt.indexOf(m) > -1; });
        if (!okMake) continue;
      }
      if (years.length && vYear && years.indexOf(vYear) < 0) continue;   // khaali = sab years

      var extra = ext(p.getValue('term_months'));
      data.plans.push({
        id: p.getUniqueValue(),
        name: p.getValue('plan_name'),
        desc: p.getValue('description'),
        price: num(p.getValue('price')),
        term: extra,                                  // standard ke upar extra months
        totalTerm: STD_MONTHS + extra,                // total months (standard + extra)
        coverageMileage: num(p.getValue('coverage_mileage_limit')),
        deductible: num(p.getValue('deductible_amount')),
        category: p.getValue('plan_category')
      });
    }
    data.plans.sort(function (a, b) { return a.price - b.price; });
  }

  // 3) Submit -> ek Warranty Registration record banao
  if (input && input.action == 'submit') {
    var f = input.form || {}, pl = new GlideRecord(T.plan);

    if (!f.inv || !data.v.inv) { data.error = 'No vehicle selected. Open this page from the Inventory record using the Warranty Registration button.'; return; }
    if (!data.o.customer) { data.error = 'No customer is set on this Inventory record.'; return; }
    if (!f.regNo || !f.invoice || !f.delivery) { data.error = 'Registration number, invoice number and purchase date are required.'; return; }
    if (!f.plan || !pl.get(f.plan)) { data.error = 'Please select a warranty plan.'; return; }

    var eligible = data.plans.some(function (x) { return x.id == f.plan; });
    if (!eligible) { data.error = 'The selected plan is not available for this vehicle.'; return; }

    // End date: UTC mein calculate karo, timezone ki wajah se date 1 din na khisak jaye
    var gdt = new GlideDateTime(f.delivery + ' 00:00:00');
    gdt.addMonthsUTC(STD_MONTHS + ext(pl.getValue('term_months')));
    gdt.addDaysUTC(-1);
    var endDate = gdt.getValue().substring(0, 10);

    var r = new GlideRecord(T.reg);
    r.initialize();                                  // Number ka default (auto number) lagta hai
    setAny(r, ['vin'], f.inv);
    setAny(r, ['customer'], data.o.customer);
    setAny(r, ['warranty_plan'], f.plan);
    setAny(r, ['delivery_date'], f.delivery);
    setAny(r, ['warranty_start_date'], f.delivery);
    setAny(r, ['warranty_end_date'], endDate);
    setAny(r, ['odometer_at_registeration', 'odometer_at_registration'], parseInt(f.odometer, 10) || 0);
    setAny(r, ['warranty_type'], String(pl.getValue('plan_category') || 'standard').toLowerCase().replace(/[^a-z0-9]+/g, '_'));
    setAny(r, ['registeration_status', 'registration_status'], 'submitted');
    setAny(r, ['registration_number'], f.regNo);
    setAny(r, ['invoice_number'], f.invoice);
    setAny(r, ['colour'], f.colour);
    setAny(r, ['owner_mobile'], f.mobile);
    setAny(r, ['owner_email'], f.email);
    setAny(r, ['id_type'], f.idType);
    setAny(r, ['id_number'], f.idNo);
    setAny(r, ['street_address'], f.street);
    setAny(r, ['city'], f.city);
    setAny(r, ['state'], f.state);
    setAny(r, ['pin_code'], f.pin);
    setAny(r, ['terms_accepted'], true);

    data.newId = r.insert();
    if (!data.newId) {
      var why = (r.getLastErrorMessage && r.getLastErrorMessage()) || '';
      data.error = 'The record could not be created (check ACLs and mandatory fields). ' + why;
      return;
    }
    data.ref = pick(r, ['number']) || String(data.newId).substring(0, 8).toUpperCase();
  }
})();
